<?php
namespace Tests\Feature;
use App\Models\Layout; use App\Models\MediaAsset; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PhaseTwoTest extends TestCase {use RefreshDatabase;
 public function test_visual_editor_requires_authentication_and_returns_draft_state():void{$layout=Layout::create(['name'=>'Escaparate','template_key'=>'full','state'=>'draft']);$layout->zones()->create(['zone_key'=>'zone_1','position'=>1]);$this->get(route('visual-editor',$layout))->assertRedirect();$this->actingAs(User::factory()->create())->getJson(route('visual-editor.state',$layout))->assertOk()->assertJsonPath('layout.name','Escaparate')->assertJsonCount(1,'layout.zones');}
 public function test_visual_editor_autosave_persists_order_and_item_options():void{$user=User::factory()->create();$media=MediaAsset::create(['display_name'=>'Foto','original_filename'=>'foto.jpg','storage_path'=>'foto.jpg','mime_type'=>'image/jpeg','media_type'=>'image','extension'=>'jpg','file_size'=>10,'sha256'=>str_repeat('b',64),'status'=>'ready']);$layout=Layout::create(['name'=>'Viejo','template_key'=>'full','state'=>'draft']);$layout->zones()->create(['zone_key'=>'zone_1','position'=>1]);$payload=['name'=>'Nuevo','template_key'=>'full','zones'=>[['key'=>'zone_1','image_fit_default'=>'cover','image_duration_default_ms'=>10000,'transition_type'=>'fade','transition_duration_ms'=>500,'items'=>[['media_asset_id'=>$media->id,'image_duration_ms'=>7000,'image_fit'=>'contain','transition_type'=>'cut','transition_duration_ms'=>250]]]]];$this->actingAs($user)->patchJson(route('visual-editor.save',$layout),$payload)->assertOk();$this->assertDatabaseHas('layouts',['id'=>$layout->id,'name'=>'Nuevo']);$this->assertDatabaseHas('playlist_items',['media_asset_id'=>$media->id,'image_duration_ms'=>7000,'transition_type'=>'cut']);}
 public function test_storage_pages_and_preflight_are_protected():void{$this->get(route('storage.index'))->assertRedirect();$this->postJson(route('storage.preflight'),['sizes'=>[1024]])->assertUnauthorized();}
}
